# python
# Robust detection with fallbacks and error handling

display(image_1)  # show original for reference

def try_detection_with_fallbacks(img):
    attempts = [
        ["plane", "car"],         # simpler/common labels
        ["airplane", "car"],      # alternate wording
        ["jet", "car"],           # original attempt but as fallback
    ]
    for objs in attempts:
        try:
            print(f"Trying detection with labels: {objs}")
            result = detection(img, objs)
            # detection is expected to return (AnnotatedImage, boxes)
            if result is None:
                print("detection returned None, trying next fallback...")
                continue
            annotated_img, boxes = result
            if annotated_img is not None and boxes:
                display(annotated_img.annotated_image)
                print("Detected boxes:", boxes)
                return annotated_img, boxes
            else:
                # Even if no boxes, show annotated image if present and continue
                if annotated_img is not None:
                    display(annotated_img.annotated_image)
                    print("No boxes returned for these labels.")
                else:
                    print("No annotated image returned.")
        except Exception as e:
            print(f"Detection attempt with labels {objs} failed with error: {e}")
    return None, None

annotated, boxes = try_detection_with_fallbacks(image_1)

if annotated is None or not boxes:
    print("Primary detection attempts failed or returned no boxes. Falling back to sliding_window_detection.")
    try:
        patches, patch_boxes = sliding_window_detection(image_1, ["plane", "car"])
        if patches:
            for i, patch in enumerate(patches):
                print(f"Patch {i+1}:")
                display(patch.annotated_image)
            print("Sliding window detected boxes per patch (w.r.t patch):", patch_boxes)
        else:
            print("sliding_window_detection returned no candidate patches.")
    except Exception as e:
        print("sliding_window_detection also failed with error:", e)

print("Finished detection/fallback attempts.")
